import json

def parse_nested_form_data(data):
    """
    Parse nested form data while preventing prototype pollution.
    """
    # Create a new dictionary to store the parsed data
    parsed_data = {}

    # Iterate over each key-value pair in the data
    for key, value in data.items():
        # Check if the key contains the __proto__ property
        if '__proto__' in key:
            # If it does, skip this key-value pair to prevent prototype pollution
            continue

        # If the value is a dictionary, recursively parse it
        if isinstance(value, dict):
            parsed_data[key] = parse_nested_form_data(value)
        else:
            # Otherwise, simply add the key-value pair to the parsed data
            parsed_data[key] = value

    return parsed_data

