import jwt
import hmac
import hashlib

def verify_token(token, secret_key):
    try:
        # Check if the secret key is empty
        if not secret_key:
            raise ValueError("Secret key cannot be empty")

        # Verify the token using the provided secret key
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        return payload
    except jwt.ExpiredSignatureError:
        return "Token has expired"
    except jwt.InvalidTokenError:
        return "Invalid token"
    except Exception as e:
        return str(e)

def generate_token(payload, secret_key):
    try:
        # Check if the secret key is empty
        if not secret_key:
            raise ValueError("Secret key cannot be empty")

        # Generate the token using the provided secret key
        token = jwt.encode(payload, secret_key, algorithm='HS256')
        return token
    except Exception as e:
        return str(e)

import ssl
import socket
from thrift.transport import TSocket
from thrift.transport import TTransport

class VerifiedTSocket(TSocket):
    def __init__(self, host, port, validate=True):
        super(VerifiedTSocket, self).__init__(host, port)
        self.validate = validate

    def makefile(self, mode):
        sock = socket.create_connection((self.host, self.port))
        if self.validate:
            context = ssl.create_default_context()
            context.check_hostname = True
            ssl_sock = context.wrap_socket(sock, server_hostname=self.host)
            return ssl_sock
        else:
            return super(VerifiedTSocket, self).makefile(mode)

class VerifiedTTransport(TTransport.TBufferedTransport):
    def __init__(self, socket):
        super(VerifiedTTransport, self).__init__(socket)

