import threading

class Throttler:
    def __init__(self, max_slots):
        self.max_slots = max_slots
        self.available_slots = max_slots
        self.lock = threading.Lock()

    def acquire_slot(self):
        with self.lock:
            if self.available_slots > 0:
                self.available_slots -= 1
                return True
            return False

    def release_slot(self):
        with self.lock:
            if self.available_slots < self.max_slots:
                self.available_slots += 1

class TrieAccountDataSync:
    def __init__(self, throttler):
        self.throttler = throttler

    def sync(self):
        if self.throttler.acquire_slot():
            try:
                # Perform trie account-data sync
                pass
            finally:
                self.throttler.release_slot()

