import ipaddress
import re

def is_private_ip(address):
    try:
        ip = ipaddress.ip_address(address)
        if isinstance(ip, ipaddress.IPv4Address):
            return ip.is_private
        elif isinstance(ip, ipaddress.IPv6Address):
            # Check for IPv4-mapped IPv6 addresses
            if ip.ipv4_mapped:
                return ipaddress.ip_address(ip.ipv4_mapped).is_private
            return False
    except ValueError:
        # If the address is not a valid IP address, it's not private
        return False

def regExpPrivateIP(address):
    # Use the is_private_ip function to check if the address is private
    if is_private_ip(address):
        return True
    # Additional checks can be added here if needed
    return False

