@app.route('/agent/<agent_id>', methods=['GET', 'PUT', 'DELETE'])
def handle_agent(agent_id):
    # Get the current workspace from the request or user session
    current_workspace = get_current_workspace()

    # Query the Agent model to check if the agent_id belongs to the current workspace
    agent = Agent.query.filter_by(id=agent_id, workspace_id=current_workspace.id).first()

    # If the agent does not exist or does not belong to the current workspace, return an error
    if agent is None:
        return jsonify({'error': 'Agent not found or not accessible in this workspace'}), 403

    # If the agent exists and belongs to the current workspace, proceed with the request
    if request.method == 'GET':
        # Handle GET request
        return jsonify({'agent': agent.serialize()})
    elif request.method == 'PUT':
        # Handle PUT request
        agent.update(request.json)
        db.session.commit()
        return jsonify({'agent': agent.serialize()})
    elif request.method == 'DELETE':
        # Handle DELETE request
        db.session.delete(agent)
        db.session.commit()
        return jsonify({'message': 'Agent deleted'})

