# Define a maximum allowed number of event tags
MAX_EVENT_TAGS = 100

def limit_event_tags(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Check if the number of event tags exceeds the maximum allowed
        if 'event_tags' in kwargs and len(kwargs['event_tags']) > MAX_EVENT_TAGS:
            logging.warning("Excessive event tags detected. Limiting to {} tags.".format(MAX_EVENT_TAGS))
            kwargs['event_tags'] = kwargs['event_tags'][:MAX_EVENT_TAGS]
        return func(*args, **kwargs)
    return wrapper

