from django.db.models import Q
from django.http import Http404

def get_event(event_uuid):
    # Assuming 'request' is the current request object and 'project' is the current project
    if not request.user.is_authenticated or not request.user.is_active:
        raise Http404("Event not found")

    # Filter events by the current project
    event = Event.objects.filter(Q(uuid=event_uuid) & Q(project=request.user.project))

    if not event.exists():
        raise Http404("Event not found")

    return event.first()

