import zipfile
import crc32c

def calculate_crc32c(data):
    """Calculates the CRC32C checksum of the given data."""
    return crc32c.crc32c(data)

def verify_zip_crc(zip_file_path):
    """Verifies the CRC of each file in the ZIP archive."""
    with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
        for info in zip_ref.infolist():
            with zip_ref.open(info.filename, 'r') as file:
                data = file.read()
                calculated_crc = calculate_crc32c(data)
                if calculated_crc != info.CRC:
                    raise ValueError(f"CRC mismatch for file {info.filename}")

