import opentelemetry.sdk.trace.export import SpanExporter
from opentelemetry.trace import Span

class BaggageSizeLimiter:
    def __init__(self, max_baggage_size):
        self.max_baggage_size = max_baggage_size

    def limit_baggage(self, span: Span):
        baggage = span.get_baggage()
        if baggage is not None:
            baggage_size = sum(len(key) + len(value) for key, value in baggage.items())
            if baggage_size > self.max_baggage_size:
                # Limit the baggage size by removing excess entries
                limited_baggage = dict(list(baggage.items())[:self.max_baggage_size])
                span.set_baggage(limited_baggage)

class SecureSpanExporter(SpanExporter):
    def __init__(self, max_baggage_size):
        self.baggage_limiter = BaggageSizeLimiter(max_baggage_size)

    def export(self, spans):
        for span in spans:
            self.baggage_limiter.limit_baggage(span)
        # Proceed with the original export logic

