import re

def validate_template(template):
    # Define a set of allowed template keys
    allowed_keys = {"metadata", "spec"}

    # Check if the template contains any disallowed keys
    for key in template.keys():
        if key not in allowed_keys:
            raise ValueError("Disallowed key in template: {}".format(key))

    # Check if the spec section contains any disallowed fields
    if "spec" in template:
        spec = template["spec"]
        disallowed_fields = ["containers", "volumes"]
        for field in disallowed_fields:
            if field in spec:
                raise ValueError("Disallowed field in spec: {}".format(field))

    # Validate the template using regular expressions
    pattern = re.compile(r"^(\{.*\})$")
    if not pattern.match(str(template)):
        raise ValueError("Invalid template format")

    return template

def sanitize_template(template):
    # Remove any disallowed fields from the template
    if "spec" in template:
        spec = template["spec"]
        disallowed_fields = ["containers", "volumes"]
        for field in disallowed_fields:
            if field in spec:
                del spec[field]

    return template

