from liquid import Template

def render_template(template_str, context):
    # Create a new Template object with a custom loader that restricts absolute paths
    class RestrictedLoader:
        def get(self, template_name):
            if os.path.isabs(template_name):
                raise ValueError("Absolute paths are not allowed")
            # Proceed with the original loader logic
            return self.original_loader.get(template_name)

    # Create a new Template object with the restricted loader
    template = Template(template_str, loader=RestrictedLoader())
    return template.render(context)

