import requests
from urllib.parse import urlparse

def sanitize_url(url):
    """Sanitizes a URL by checking its scheme and netloc."""
    try:
        parsed_url = urlparse(url)
        if parsed_url.scheme not in ['http', 'https']:
            raise ValueError("Invalid URL scheme")
        if not parsed_url.netloc:
            raise ValueError("Invalid URL netloc")
        return url
    except ValueError as e:
        print(f"Error sanitizing URL: {e}")
        return None

def patched_api_client(url, params=None):
    """Patched API client function that sanitizes the URL before making a request."""
    sanitized_url = sanitize_url(url)
    if sanitized_url:
        response = requests.get(sanitized_url, params=params)
        return response.json()
    else:
        return None

