def sanitize_import(module_name):
    try:
        # Attempt to import the module
        module = importlib.import_module(module_name)

        # Basic validation: check if the module has any suspicious attributes
        for attr in dir(module):
            if attr.startswith('__') and attr.endswith('__'):
                continue  # Ignore built-in attributes
            if callable(getattr(module, attr)):
                # If an attribute is callable, it could be a potential entry point for malicious code
                print(f"Warning: {module_name} has a potentially suspicious attribute: {attr}")

        return module

    except ImportError as e:
        # Handle import errors
        print(f"Error importing {module_name}: {e}")
        return None

