from spring_kafka import KafkaTemplate

# Set a maximum size for the delegate cache to prevent unbounded growth
MAX_CACHE_SIZE = 1000

class BoundedDelegateCache:
    def __init__(self):
        self.cache = {}
        self.cache_size = 0

    def get(self, key):
        return self.cache.get(key)

    def put(self, key, value):
        if self.cache_size >= MAX_CACHE_SIZE:
            # Remove the oldest item from the cache when it reaches the maximum size
            self.cache.pop(next(iter(self.cache)))
            self.cache_size -= 1
        self.cache[key] = value
        self.cache_size += 1

# Create a Kafka template with the bounded delegate cache
kafka_template = KafkaTemplate(delegate_cache=BoundedDelegateCache())

