import websocket
import urllib.parse

def sanitize_header(header):
    """Sanitize a WebSocket response header by removing non-ASCII characters."""
    return ''.join(char for char in header if ord(char) < 128)

def patched_websocket_recv(ws):
    """Patch the WebSocket receive function to sanitize response headers."""
    frame = ws.recv_frame()
    if frame.opcode == websocket.ABNF.OPCODE_CLOSE:
        # Sanitize close frame headers
        close_frame = websocket.AbnfCloseFrame()
        close_frame.parse(frame)
        close_frame.headers = {key: sanitize_header(value) for key, value in close_frame.headers.items()}
        return close_frame
    elif frame.opcode == websocket.ABNF.OPCODE_PING:
        # Sanitize ping frame headers
        ping_frame = websocket.AbnfPingFrame()
        ping_frame.parse(frame)
        ping_frame.headers = {key: sanitize_header(value) for key, value in ping_frame.headers.items()}
        return ping_frame
    else:
        # Sanitize other frame headers
        frame.headers = {key: sanitize_header(value) for key, value in frame.headers.items()}
        return frame

# Example usage:
