import os

class SecureFileTemplateLoader:
    def __init__(self, base_dir):
        self.base_dir = base_dir

    def get_template(self, template_name):
        # Normalize the template name to prevent path traversal
        template_name = os.path.normpath(template_name)
        # Remove any leading slashes to prevent absolute paths
        template_name = template_name.lstrip('/')
        # Join the base directory and template name to ensure the file is within the intended directory
        file_path = os.path.join(self.base_dir, template_name)
        # Check if the file is within the base directory to prevent path traversal
        if not file_path.startswith(self.base_dir):
            raise ValueError("Template file is outside the base directory")
        # Return the file path if it exists and is a file
        if os.path.isfile(file_path):
            return file_path
        else:
            return None

