# Define a function to remove OAuth credentials from URLs
def remove_oauth_credentials(url):
    parsed_url = urlparse(url)
    query_params = parsed_url.query.split('&')
    filtered_query_params = [param for param in query_params if not param.startswith('oauth_') and not param.startswith('access_token') and not param.startswith('client_id') and not param.startswith('client_secret')]
    filtered_query_string = '&'.join(filtered_query_params)
    return urlunparse((parsed_url.scheme, parsed_url.netloc, parsed_url.path, parsed_url.params, filtered_query_string, parsed_url.fragment))

# Define a function to handle exceptions and remove OAuth credentials from error messages
def handle_exception(exception):
    error_message = str(exception)
    # Remove OAuth credentials from the error message
    error_message = error_message.replace('oauth_', '[REDACTED]').replace('access_token', '[REDACTED]').replace('client_id', '[REDACTED]').replace('client_secret', '[REDACTED]')
    logger.error(error_message)
    return jsonify({'error': error_message}), 500

