import oj

class SafeDocIterator:
    def __init__(self, doc):
        self.doc = doc
        self.closed = False

    def __iter__(self):
        return self

    def __next__(self):
        if self.closed:
            raise StopIteration
        try:
            return next(self.doc)
        except StopIteration:
            self.closed = True
            raise

    def close(self):
        if not self.closed:
            self.doc.close()
            self.closed = True

def safe_iter(doc):
    return SafeDocIterator(doc)

