from werkzeug.datastructures import MIMEAccept

def validate_accept_header():
    accept_header = request.headers.get('Accept')
    if accept_header:
        mime_accept = MIMEAccept(accept_header)
        if '*/*' in mime_accept.best_match(['application/json', 'text/html']):
            # If the Accept header is set to */*, it's likely a CORS request
            # and we should validate it further to prevent CSRF bypass
            if not validate_cors_request():
                return False
    return True

