from hashlib import hmac
from symfony import ux_live_component

def generate_hmac_checksum(component, slot, data):
    # Include component and slot in the HMAC checksum
    checksum_data = f"{component}:{slot}:{data}"
    return hmac.new(ux_live_component.secret_key, checksum_data.encode(), 'sha256').hexdigest()

def verify_hmac_checksum(component, slot, data, expected_checksum):
    # Regenerate the HMAC checksum with the component and slot
    actual_checksum = generate_hmac_checksum(component, slot, data)
    return hmac.compare_digest(actual_checksum, expected_checksum)

