import time
from functools import wraps

# Define a rate limit for batch action requests (e.g., 10 requests per minute)
RATE_LIMIT = 10
TIME_WINDOW = 60  # seconds

# Create a dictionary to store request timestamps for each client IP
request_timestamps = {}

def rate_limit_batch_actions(func):
    @wraps(func)
    def wrapper(request, *args, **kwargs):
        client_ip = request.remote_addr
        current_time = time.time()

        # Initialize the list of timestamps for the client IP if it doesn't exist
        if client_ip not in request_timestamps:
            request_timestamps[client_ip] = []

        # Remove timestamps that are older than the time window
        request_timestamps[client_ip] = [timestamp for timestamp in request_timestamps[client_ip] if current_time - timestamp < TIME_WINDOW]

        # Check if the rate limit has been exceeded
        if len(request_timestamps[client_ip]) >= RATE_LIMIT:
            return "Rate limit exceeded", 429

        # Add the current timestamp to the list
        request_timestamps[client_ip].append(current_time)

        # Call the original function
        return func(request, *args, **kwargs)

    return wrapper

# Apply the rate limit decorator to the batch action function
@rate_limit_batch_actions
