class DefaultCookieStorage:
    def __init__(self):
        self.cookies = {}

    def add_cookie(self, cookie: Cookie):
        # Enforce domain and path scoping
        if cookie.domain and cookie.path:
            key = (cookie.domain, cookie.path)
            self.cookies[key] = cookie
        else:
            # Handle cases where domain or path is not specified
            self.cookies[cookie.name] = cookie

    def get_cookies(self, request: Request):
        # Filter cookies based on the request's domain and path
        relevant_cookies = []
        for key, cookie in self.cookies.items():
            if isinstance(key, tuple) and key[0] == request.domain and key[1] == request.path:
                relevant_cookies.append(cookie)
            elif isinstance(key, str) and key == request.domain:
