from http_proxy_middleware import Router

class SecureRouter(Router):
    def __init__(self, options):
        super().__init__(options)
        self.options['strict'] = True  # Enable strict matching by default

    def match(self, host, path):
        if self.options['strict']:
            # Use exact matching instead of substring matching
            return host == self.options['host'] and path == self.options['path']
        else:
            # Fallback to original behavior if strict matching is disabled
            return super().match(host, path)

