import os
import zipfile

def validate_zip_file(zip_file):
    """
    Validate the contents of a zip file to prevent arbitrary file read.
    """
    try:
        with zipfile.ZipFile(zip_file, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                file_name = file_info.filename
                # Check if the file name is a symlink
                if os.path.islink(file_name):
                    raise ValueError("Symlink detected in zip file")
                # Check if the file name contains ../ to prevent directory traversal
                if "../" in file_name:
                    raise ValueError("Directory traversal detected in zip file")
    except zipfile.BadZipFile:
        raise ValueError("Invalid zip file")
    except Exception as e:
        raise ValueError("Error validating zip file: {}".format(str(e)))

def secure_upload(zip_file):
    """
    Securely upload a zip file by validating its contents.
