import bcrypt

def hash_password(password):
    # Increase the number of salt rounds to 12 (or more) for better security
    salt_rounds = 12
    salt = bcrypt.gensalt(salt_rounds)
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
