import threading

class RecoveryCodeManager:
    def __init__(self):
        self.recovery_codes = {}
        self.lock = threading.Lock()

    def add_recovery_code(self, code, max_uses=1):
        with self.lock:
            self.recovery_codes[code] = {'uses': 0, 'max_uses': max_uses}

    def use_recovery_code(self, code):
        with self.lock:
            if code in self.recovery_codes:
                recovery_code_info = self.recovery_codes[code]
                if recovery_code_info['uses'] < recovery_code_info['max_uses']:
                    recovery_code_info['uses'] += 1
                    return True
        return False

    def reset_recovery_code(self, code):
        with self.lock:
            if code in self.recovery_codes:
                self.recovery_codes[code]['uses'] = 0

