from flask import request, jsonify
from kimai import db
from kimai.models import User, Timesheet, FavoriteTimesheet

# Define a function to validate user ownership of a timesheet
def validate_user_ownership(timesheet_id, user_id):
    timesheet = Timesheet.query.get(timesheet_id)
    if timesheet.user_id != user_id:
        return False
    return True

# Define a function to add a favorite timesheet
def add_favorite_timesheet(timesheet_id, user_id):
    if validate_user_ownership(timesheet_id, user_id):
        favorite_timesheet = FavoriteTimesheet.query.filter_by(timesheet_id=timesheet_id, user_id=user_id).first()
        if favorite_timesheet is None:
            favorite_timesheet = FavoriteTimesheet(timesheet_id=timesheet_id, user_id=user_id)
            db.session.add(favorite_timesheet)
            db.session.commit()
            return jsonify({"message": "Timesheet added to favorites"}), 200
        else:
            return jsonify({"message": "Timesheet already in favorites"}), 400
    else:
        return jsonify({"message": "Unauthorized access"}), 401

# Define a function to remove a favorite timesheet
def remove_favorite_timesheet(timesheet_id, user_id):
    if validate_user_ownership(timesheet_id, user_id):
        favorite_timesheet = FavoriteTimesheet.query.filter_by(timesheet_id=timesheet_id, user_id=user_id).first()
        if favorite_timesheet is not None:
            db.session.delete(favorite_timesheet)
            db.session.commit()
            return jsonify({"message": "Timesheet removed from favorites"}), 200
        else:
            return jsonify({"message": "Timesheet not in favorites"}), 400
    else:
        return jsonify({"message": "Unauthorized access"}), 401

