import subprocess
import ast

def safe_execute(command):
    # Basic validation to prevent obvious command injection
    if not isinstance(command, str):
        raise TypeError("Command must be a string")
    if ".." in command or "/" in command or "\\" in command:
        raise ValueError("Potential path traversal detected")

    # Using subprocess with shell=False to prevent shell injection
    try:
        subprocess.run(command.split(), check=True, shell=False)
    except subprocess.CalledProcessError as e:
        print(f"Command failed with return code {e.returncode}")

def safe_eval(expression):
    # Using ast to safely evaluate expressions
    try:
        ast.parse(expression)
        return eval(expression)
    except SyntaxError:
        raise ValueError("Invalid expression")
    except Exception as e:
        raise ValueError("Failed to evaluate expression") from e

