from starlette.datastructures import URL
from starlette.requests import Request
from starlette.types import ASGI_APP, Receive, Scope, Send

class HostHeaderValidationMiddleware:
    def __init__(self, app: ASGI_APP):
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send):
        if scope["type"] == "http":
            request = Request(scope)
            host = request.headers.get("host")
            if host and not self._is_valid_host(host, request.url):
                # Handle invalid host, e.g., return a 400 error
                await send({
                    "type": "http.response.start",
                    "status": 400,
                    "headers": [(b"content-type", b"text/plain")]
                })
                await send({
                    "type": "http.response.body",
                    "body": b"Invalid Host header",
                    "more_body": False
                })
                return

        await self.app(scope, receive, send)

    def _is_valid_host(self, host: str, url: URL) -> bool:
        # Implement your host validation logic here
        # For example, you can check if the host matches the expected domain
        expected_domain = "example.com"
        return host.endswith(expected_domain)

