import sys

def secure_import(module_name):
    """
    Securely imports a module, checking for potential malicious code.
    """
    try:
        # Check if the module is a built-in module
        if module_name in sys.builtin_module_names:
            return importlib.import_module(module_name)
        # Check if the module is a local module
        elif importlib.find_loader(module_name):
            return importlib.import_module(module_name)
        else:
            # If the module is not found, raise an exception
            raise ImportError(f"Module {module_name} not found")
    except Exception as e:
        # Log the exception and raise a custom error
        print(f"Error importing module {module_name}: {str(e)}")
        raise ImportError(f"Failed to import module {module_name}")

