import json
from urllib.parse import urlparse

def validate_harpoon_package(package_url):
    """
    Validate the harpoon-package URL to prevent malicious code execution.
    """
    try:
        # Parse the URL to extract its components
        parsed_url = urlparse(package_url)

        # Check if the URL scheme is valid (e.g., https)
        if parsed_url.scheme not in ['https']:
            return False

        # Validate the network location (e.g., npm repository)
        if 'npm' not in parsed_url.netloc:
            return False

        # If all checks pass, the URL is likely valid
        return True

    except ValueError:
        # If URL parsing fails, the URL is likely malicious
        return False

def sanitize_harpoon_package_data(data):
    """
    Sanitize the harpoon-package data to prevent code injection.
    """
    try:
        # Load the JSON data
        json_data = json.loads(data)

        # Remove any suspicious or unauthorized keys
        for key in list(json_data.keys()):
            if key.startswith('__') or key.endswith('__'):
                del json_data[key]

        # Return the sanitized data
        return json.dumps(json_data)

    except json.JSONDecodeError:
        # If JSON decoding fails, the data is likely malicious
        return None

import importlib
import importlib.util
import os

def safe_import(module_name):
    # Check if the module is a known, trusted module
    trusted_modules = ['module1', 'module2']  # List of trusted modules
    if module_name not in trusted_modules:
        raise ImportError(f"Module {module_name} is not trusted")

    # Attempt to import the module
    try:
        spec = importlib.util.find_spec(module_name)
        if spec is None:
            raise ImportError(f"Module {module_name} not found")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module
    except Exception as e:
        raise ImportError(f"Failed to import {module_name}: {e}")

