import html

# Assuming fabric.Gradient is a class with a colorStops attribute
class FabricGradient:
    def __init__(self, color_stops):
        self.color_stops = self.sanitize_color_stops(color_stops)

    def sanitize_color_stops(self, color_stops):
        sanitized_stops = []
        for stop in color_stops:
            # Sanitize the color stop values to prevent XSS
            sanitized_stop = {
                'offset': html.escape(stop['offset']),
                'color': html.escape(stop['color'])
            }
            sanitized_stops.append(sanitized_stop)
        return sanitized_stops

    def to_svg(self):
        # Example method to serialize to SVG, using sanitized color stops
        svg = '<linearGradient>'
        for stop in self.color_stops:
            svg += f'<stop offset="{stop["offset"]}" stop-color="{stop["color"]}"/>'
        svg += '</linearGradient>'
        return svg

