from authlib.integrations.base_client import ClientIntegration

def validate_redirect_uri(client, redirect_uri):
    """Validate the redirect URI against the client's registered redirect URIs"""
    registered_uris = client.redirect_uris
    parsed_uri = urlparse(redirect_uri)
    for registered_uri in registered_uris:
        registered_parsed_uri = urlparse(registered_uri)
        if (parsed_uri.scheme, parsed_uri.netloc) == (registered_parsed_uri.scheme, registered_parsed_uri.netloc):
            # If the scheme and netloc match, allow the redirect URI
            return True
    # If no match is found, reject the redirect URI
    return False

