import reactor.netty.http.client.HttpClient
from reactor.util.Logger import logger

def patch_http_client():
    # Create a custom HttpClient that overrides the redirect behavior
    class CustomHttpClient(HttpClient):
        def _handle_redirect(self, response, request):
            # Check if the redirect is from HTTPS to HTTP
            if response.status().code() == 301 or response.status().code() == 302:
                if request.uri().getScheme() == 'https' and response.headers().get('Location').split(':')[0] == 'http':
                    # Do not include credentials in the redirected request
                    request = request.mutable().header('Authorization', None)
            return super()._handle_redirect(response, request)

    # Replace the default HttpClient with the custom one
    reactor.netty.http.client.HttpClient = CustomHttpClient

# Apply the patch
