import io
from netty.codec.http2 import DelegatingDecompressorFrameListener

class PatchedDelegatingDecompressorFrameListener(DelegatingDecompressorFrameListener):
    def onData(self, data):
        try:
            # Call the original onData method
            super().onData(data)
        finally:
            # Ensure the byte buffer is released
            if data is not None:
                data.release()

    def onHeaders(self, headers):
        try:
            # Call the original onHeaders method
            super().onHeaders(headers)
        finally:
            # Ensure any byte buffers in the headers are released
            for header in headers:
                if isinstance(header, io.ByteBuffer):
                    header.release()

import io.netty.handler.codec.dns.*;

class DnsResponseHandler {
    public void handleDnsResponse(DnsResponse response) {
        // Iterate over each answer in the DNS response
        for (DnsSection section : response.sections()) {
            for (DnsRecord record : section.records()) {
                if (record.type() == DnsRecordType.CNAME) {
                    // Perform bailiwick check for CNAME records
                    DnsCnameRecord cnameRecord = (DnsCnameRecord) record;
                    String canonicalName = cnameRecord.canonicalName();
                    if (!isBailiwickValid(response, canonicalName)) {
                        // Reject the DNS response if the bailiwick check fails
                        throw new DnsResponseException("Bailiwick check failed for CNAME record");
                    }
                }
            }
        }
    }

    private boolean isBailiwickValid(DnsResponse response, String canonicalName) {
        // Perform bailiwick check by verifying that the canonical name is within the same domain
        String[] canonicalNameParts = canonicalName.split("\\.");
        String[] responseDomainParts = response.domain().split("\\.");
        if (canonicalNameParts.length < responseDomainParts.length) {
            return false;
        }
        for (int i = 0; i < responseDomainParts.length; i++) {
            if (!canonicalNameParts[canonicalNameParts.length - 1 - i].equals(responseDomainParts[responseDomainParts.length - 1 - i])) {
                return false;
            }
        }
        return true;
    }
}

