import org.springframework.http.HttpMethod
import org.springframework.http.server.reactive.ServerHttpRequest
import org.springframework.web.server.ServerWebExchange

# Define a custom filter to validate and limit multipart requests
class MultipartRequestFilter:
    def filter(self, exchange: ServerWebExchange):
        request = exchange.getRequest()
        if request.getMethod() == HttpMethod.POST and 'multipart/' in request.getHeaders().getContentType():
            # Limit the maximum size of multipart requests to 10MB
            max_size = 10 * 1024 * 1024
            content_length = request.getHeaders().getContentLength()
            if content_length > max_size:
                # Return a 413 error response if the request exceeds the maximum size
                exchange.getResponse().setStatusCode(413)
                exchange.getResponse().getHeaders().setContentType('text/plain')
                exchange.getResponse().getBody().sendString('Request entity too large')
                return
        # Proceed with the request if it's valid
        return exchange.getNext()

# Register the custom filter in the Spring application
class WebFluxConfig:
    def __init__(self):
        self.multipart_request_filter = MultipartRequestFilter()

    def filter(self):
        return self.multipart_request_filter

