import hashlib

def generate_cache_key(request):
    # Create a unique cache key based on the request URL, method, and headers
    cache_key = hashlib.sha256()
    cache_key.update(request.url.encode())
    cache_key.update(request.method.encode())
    for header, value in request.headers.items():
        cache_key.update(f"{header}:{value}".encode())
    return cache_key.hexdigest()

class HttpTransferCache:
    def __init__(self):
        self.cache = {}

    def get(self, request):
        cache_key = generate_cache_key(request)
        return self.cache.get(cache_key)

    def set(self, request, response):
        cache_key = generate_cache_key(request)
        self.cache[cache_key] = response

