import csv
import subprocess

def safe_execute_command(command):
    # Define a whitelist of allowed commands
    allowed_commands = ["ls", "echo", "cat"]

    # Split the command into individual arguments
    args = command.split()

    # Check if the command is in the whitelist
    if args[0] not in allowed_commands:
        raise ValueError("Command not allowed")

    # Use subprocess with a whitelist of allowed commands
    try:
        output = subprocess.check_output(args)
        return output.decode("utf-8")
    except subprocess.CalledProcessError as e:
        return f"Error: {e}"

def parse_csv_file(file_path):
    with open(file_path, 'r') as file:
        csv_reader = csv.reader(file)
        for row in csv_reader:
            # Assume the first column contains commands to execute
            command = row[0]
            try:
                output = safe_execute_command(command)
                print(output)
            except ValueError as e:
                print(f"Error: {e}")

