import jsonpatch

def apply_json_patch(data, patch):
    # Validate the patch operations to ensure only allowed operations are performed
    allowed_operations = ['add', 'remove', 'replace', 'move', 'copy', 'test']
    for operation in patch:
        if operation['op'] not in allowed_operations:
            raise ValueError(f"Operation '{operation['op']}' is not allowed")

        # Restrict path modifications to prevent data tampering
        if operation['op'] in ['add', 'replace'] and '/-sensitive-data/' in operation['path']:
            raise ValueError(f"Modification of sensitive data is not allowed")

    # Apply the validated patch operations
    patched_data = jsonpatch.apply_patch(data, patch)
    return patched_data

