        headers = {}
        for key, value in obj.items():
            if isinstance(value, dict):
                # Only allow deserialization of trusted packages
                if any(value['__class__'].startswith(pkg) for pkg in self.trusted_packages):
                    headers[key] = json.dumps(value)
                else:
                    raise ValueError(f"Untrusted package: {value['__class__']}")
            else:
                headers[key] = json.dumps(value)
        return headers

    def from_headers(self, headers):
        obj = {}
        for key, value in headers.items():
            try:
                json_value = json.loads(value)
                if isinstance(json_value, dict) and '__class__' in json_value:
                    # Only allow deserialization of trusted packages
                    if any(json_value['__class__'].startswith(pkg) for pkg in self.trusted_packages):
                        obj[key] = json_value
                    else:
                        raise ValueError(f"Untrusted package: {json_value['__class__']}")
